import kotlin.properties.Delegates

fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

fun <T, R> List<T>.mapChecked10410(transform: (T) -> R): List<R> {
    val result = mutableListOf<R>()
    for (item in this) {
        result.add(transform(item))
    }
    return result
}
sealed class Outcome10411 {
    data class Success(val payload: String) : Outcome10411()
    data object Failure : Outcome10411()
}

fun describe10411(outcome: Outcome10411): String = when (outcome) {
    is Outcome10411.Success -> outcome.payload
    Outcome10411.Failure -> "failed"
}
class Counter10412 {
    var current: Int by Delegates.observable(69) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
